def splitArray(nums, k):
    def pieces(limit):
        count, cur = 1, 0
        for x in nums:
            if cur + x > limit:
                count += 1
                cur = 0
            cur += x
        return count

    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if pieces(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
